import base64
import io
import json
import math
import os
import random
import sys
import traceback
from itertools import combinations
for _v in ('OMP_NUM_THREADS', 'OPENBLAS_NUM_THREADS', 'MKL_NUM_THREADS', 'VECLIB_MAXIMUM_THREADS', 'NUMEXPR_NUM_THREADS'):
    os.environ.setdefault(_v, '1')
import numpy as np
_ACT_NPZ_B64 = ''
_DISC_NPZ_B64 = ''

def _load_npz_b64(b64):
    with np.load(io.BytesIO(base64.b64decode(b64)), allow_pickle=False) as z:
        return {k: z[k] for k in z.files}
CARD_ID = {}
for _s, _suit in enumerate('cdhs'):
    for _r, _rank in enumerate('23456789TJQKA'):
        CARD_ID[_rank + _suit] = _s * 13 + _r + 1
N_HIST = 32
N_TOK_ACT = 41
N_TOK_DISC = 8
N_CTX_ACT = 17
N_CTX_DISC = 16
N_ACT = 6
_SI = {'preflop': 0, 'flop': 1, 'turn': 2, 'river': 3}
_AI = {'fold': 0, 'check': 1, 'call': 2, 'raise': 3}
_SEATS = {'button': 0, 'big_blind': 1}

def card_id(s):
    return CARD_ID[s] if s else 0

def _eval5(cards):
    ranks = sorted(((c - 1) % 13 for c in cards))
    suits = [(c - 1) // 13 for c in cards]
    flush = len(set(suits)) == 1
    uniq = sorted(set(ranks), reverse=True)
    straight_hi = -1
    if len(uniq) == 5:
        if uniq[0] - uniq[4] == 4:
            straight_hi = uniq[0]
        elif uniq == [12, 3, 2, 1, 0]:
            straight_hi = 3
    if flush and straight_hi >= 0:
        return (8, [straight_hi])
    cnt = {}
    for r in ranks:
        cnt[r] = cnt.get(r, 0) + 1
    groups = sorted(cnt.items(), key=lambda kv: (kv[1], kv[0]), reverse=True)
    if groups[0][1] == 4:
        return (7, [groups[0][0], groups[1][0]])
    if groups[0][1] == 3 and groups[1][1] == 2:
        return (6, [groups[0][0], groups[1][0]])
    if flush:
        return (5, uniq)
    if straight_hi >= 0:
        return (4, [straight_hi])
    if groups[0][1] == 3:
        kick = [g[0] for g in groups[1:]]
        return (3, [groups[0][0]] + kick)
    if groups[0][1] == 2 and groups[1][1] == 2:
        kick = max((g[0] for g in groups[2:]))
        return (2, [groups[0][0], groups[1][0], kick])
    if groups[0][1] == 2:
        kick = [g[0] for g in groups[1:]]
        return (1, [groups[0][0]] + kick)
    return (0, uniq)

def _best(cards):
    best = None
    for combo in combinations(cards, 5):
        ev = _eval5(combo)
        key = (ev[0], ev[1])
        if best is None or key > best:
            best = key
    return best

def hand_strength(hole_ids, board_ids):
    cards = [c for c in hole_ids + board_ids if c]
    if len(cards) >= 5:
        cat, kick = _best(cards)
        minor = sum((k * 13 ** (3 - i) for i, k in enumerate(kick[:4])))
        return (cat + minor / 13 ** 4) / 9.0
    cnt = {}
    for c in cards:
        cnt[(c - 1) % 13] = cnt.get((c - 1) % 13, 0) + 1
    top = max(cnt.values())
    hi = max(cnt) / 12.0
    if top == 3:
        return 0.4 + 0.05 * hi
    if top == 2:
        return 0.25 + 0.08 * hi
    return 0.15 * hi

def legal_mask(req):
    la = req.get('legal_actions') or []
    to_call = req.get('to_call') or 0
    can_raise = 'raise' in la and (req.get('raises_left') or 0) > 0 and ((req.get('min_raise') or 0) <= (req.get('max_raise') or 0))
    m = np.zeros(N_ACT, dtype=np.uint8)
    m[0] = to_call > 0 and 'fold' in la
    m[1] = 'check' in la or (to_call > 0 and 'call' in la)
    m[2] = m[3] = m[4] = can_raise
    m[5] = can_raise and (req.get('my_stack') or 0) > 0
    return m

def decode_bucket(act_idx, req):
    legal = req['legal_actions']
    to_call = req['to_call']
    street = req['street']
    pot = req['pot']
    opp_bet = req['opp_bet']
    if act_idx == 0 and to_call > 0 and ('fold' in legal):
        return {'type': 'action', 'action': 'fold'}
    if act_idx == 1 or 'raise' not in legal or req.get('raises_left', 0) <= 0:
        if 'check' in legal:
            return {'type': 'action', 'action': 'check'}
        if 'call' in legal:
            return {'type': 'action', 'action': 'call'}
        return {'type': 'action', 'action': 'fold'}
    min_r = req['min_raise']
    max_r = req['max_raise']
    if street == 'preflop':
        if act_idx == 2:
            amt = max(min_r, min(4, max_r))
        elif act_idx == 3:
            if to_call > 0 and opp_bet <= 2:
                r_seed = (int(req.get('hand_id', 1)) * 37 + int(req.get('my_stack', 200))) % 100
                if r_seed < 35:
                    amt = max(min_r, min(4, max_r))
                elif r_seed < 75:
                    amt = max(min_r, min(5, max_r))
                else:
                    amt = max(min_r, min(6, max_r))
            else:
                amt = opp_bet + max(3, int(pot * 0.8)) if to_call > 0 else max(min_r, 6)
        elif act_idx == 4:
            r_seed = (int(req.get('hand_id', 1)) * 53 + int(pot)) % 100
            mult = 2.45 if r_seed < 33 else 2.85 if r_seed < 67 else 3.15
            amt = int(opp_bet * mult) + 2 if opp_bet >= 4 else max(min_r, 8)
        else:
            amt = max_r
    else:
        eff_pot = pot + to_call
        if act_idx == 2:
            amt = opp_bet + max(2, int(eff_pot * 0.4))
        elif act_idx == 3:
            amt = opp_bet + max(4, int(eff_pot * 0.72))
        elif act_idx == 4:
            amt = opp_bet + max(8, int(eff_pot * 1.15))
        else:
            amt = max_r
    amt = max(min_r, min(max_r, int(amt)))
    return {'type': 'action', 'action': 'raise', 'amount': amt}
D, HEADS, FFN, LAYERS = (128, 4, 512, 4)
DH = D // HEADS

def _np_erf(x):
    a1, a2, a3, a4, a5 = (0.254829592, -0.284496736, 1.421413741, -1.453152027, 1.061405429)
    p = 0.3275911
    z = np.abs(x)
    t = 1.0 / (1.0 + p * z)
    y = 1.0 - ((((a5 * t + a4) * t + a3) * t + a2) * t + a1) * t * np.exp(-z * z)
    return np.sign(x) * y

def _gelu(x):
    return 0.5 * x * (1.0 + _np_erf(x * (1.0 / math.sqrt(2.0))))

def _layer_norm(x, w, b, eps=1e-05):
    m = x.mean(axis=-1, keepdims=True)
    v = x.var(axis=-1, keepdims=True)
    return (x - m) / np.sqrt(v + eps) * w + b

def _softmax_last(x):
    x = x - x.max(axis=-1, keepdims=True)
    e = np.exp(x)
    return e / e.sum(axis=-1, keepdims=True)

def _map_tokens(t):
    t = np.asarray(t, dtype=np.int64)
    return np.where(t < 53, t, 52 + np.clip(t, 1, 32))

class NumpyPolicy:

    def __init__(self, sd, n_tok=N_TOK_ACT, n_ctx=N_CTX_ACT, n_act=N_ACT, map_tokens=True):
        self.sd = {k: np.ascontiguousarray(v, dtype=np.float32) for k, v in sd.items()}
        self.n_tok, self.n_ctx, self.n_act = (n_tok, n_ctx, n_act)
        self.map_tokens = map_tokens

    def forward(self, tokens, ctx):
        sd = self.sd
        tok = _map_tokens(tokens) if self.map_tokens else np.asarray(tokens, dtype=np.int64)
        x = sd['emb.weight'][tok] + sd['pos.weight'][None, :self.n_tok, :]
        cx = ctx.astype(np.float32)
        cx = _layer_norm(cx, sd['ctx_proj.0.weight'], sd['ctx_proj.0.bias'])
        cx = cx @ sd['ctx_proj.1.weight'].T + sd['ctx_proj.1.bias']
        x = x + cx[:, None, :]
        for i in range(LAYERS):
            p = f'blocks.{i}.'
            h = _layer_norm(x, sd[p + 'ln1.weight'], sd[p + 'ln1.bias'])
            qkv = h @ sd[p + 'qkv.weight'].T + sd[p + 'qkv.bias']
            B, T, _ = qkv.shape
            q, k, v = np.split(qkv, 3, axis=-1)
            q = q.reshape(B, T, HEADS, DH).transpose(0, 2, 1, 3)
            k = k.reshape(B, T, HEADS, DH).transpose(0, 2, 1, 3)
            v = v.reshape(B, T, HEADS, DH).transpose(0, 2, 1, 3)
            att = _softmax_last(q @ k.transpose(0, 1, 3, 2) / math.sqrt(DH))
            h = (att @ v).transpose(0, 2, 1, 3).reshape(B, T, D)
            x = x + h @ sd[p + 'proj.weight'].T + sd[p + 'proj.bias']
            h = _layer_norm(x, sd[p + 'ln2.weight'], sd[p + 'ln2.bias'])
            h = _gelu(h @ sd[p + 'fc1.weight'].T + sd[p + 'fc1.bias'])
            x = x + h @ sd[p + 'fc2.weight'].T + sd[p + 'fc2.bias']
        x = _layer_norm(x, sd['ln_f.weight'], sd['ln_f.bias'])
        pooled = x.mean(axis=1)
        return pooled @ sd['head.weight'].T + sd['head.bias']
POLICY = None
DISC = None
RNG = random.SystemRandom()

def load_models():
    global POLICY, DISC
    POLICY = NumpyPolicy(_load_npz_b64(_ACT_NPZ_B64))
    DISC = NumpyPolicy(_load_npz_b64(_DISC_NPZ_B64), n_tok=N_TOK_DISC, n_ctx=N_CTX_DISC, n_act=3, map_tokens=False)

class HandState:
    __slots__ = ('hand', 'seat', 'hole', 'opp_disc', 'seq')

    def __init__(self):
        self.hand = self.seat = 0
        self.hole = []
        self.opp_disc = None
        self.seq = 0
H = HandState()

def card_ids(cards):
    return [CARD_ID[c] for c in cards if c]

def build_act_features(msg):
    hole = card_ids(H.hole)
    board = card_ids(msg['board'])
    req = {k: v for k, v in msg.items() if k not in ('history', 'time_left_ms', 'type', 'hand_id')}
    req['hand_id'] = msg['hand_id']
    hist = msg['history']
    toks = np.zeros(N_TOK_ACT, dtype=np.int64)
    toks[0:len(hole)] = hole
    toks[3:3 + len(board)] = board
    toks[8] = card_id(H.opp_disc) if H.opp_disc else 0
    for i, h in enumerate(hist[-N_HIST:]):
        toks[9 + i] = (_SI[h['street']] * 2 + (0 if h['actor'] == 'me' else 1)) * 4 + _AI[h['action']] + 1
    st = _SI[msg['street']]
    ctx = np.zeros(N_CTX_ACT, dtype=np.float32)
    ctx[st] = 1.0
    pot = msg.get('pot') or 0
    ctx[4] = pot / 200.0
    ctx[5] = (msg.get('to_call') or 0) / 200.0
    ctx[6] = (msg.get('my_bet') or 0) / 200.0
    ctx[7] = (msg.get('opp_bet') or 0) / 200.0
    ctx[8] = (msg.get('my_stack') or 0) / 200.0
    ctx[9] = (msg.get('opp_stack') or 0) / 200.0
    ctx[10] = (msg.get('min_raise') or 0) / 200.0
    ctx[11] = (msg.get('max_raise') or 0) / 200.0
    ctx[12] = (msg.get('raises_left') or 0) / 3.0
    ctx[13] = hand_strength(hole, board)
    ctx[14] = 0.0
    ctx[15] = len(hist) / N_HIST
    ctx[16] = (msg.get('time_left_ms') or 30000) / 30000.0
    return (toks, ctx, req, pot, st)

def handle_action(msg):
    toks, ctx, req, pot, st = build_act_features(msg)
    legal = legal_mask(req)
    logits = POLICY.forward(toks[None], ctx[None])[0].astype(np.float64)
    masked = np.where(legal != 0, logits, -np.inf)
    m = masked.max()
    p = np.exp(masked - m)
    p /= p.sum()
    b = int(RNG.choices(range(N_ACT), weights=p)[0])
    rep = decode_bucket(b, req)
    return rep

def handle_discard(msg):
    hole = card_ids(msg['hole_cards'])
    board = card_ids(msg['board'])
    toks = np.zeros(N_TOK_DISC, dtype=np.int64)
    toks[0:len(hole)] = hole
    toks[3:3 + len(board)] = board
    ctx = np.zeros(N_CTX_DISC, dtype=np.float32)
    st = {0: 0, 1: 1, 2: 1, 3: 1, 4: 2, 5: 3}.get(len(board), 3)
    ctx[st] = 1.0
    ctx[4] = (msg.get('pot') or 0) / 200.0
    ctx[5] = (msg.get('my_stack') or 0) / 200.0
    ctx[6] = (msg.get('opp_stack') or 0) / 200.0
    for i, c in enumerate(hole):
        r = (c - 1) % 13
        s = (c - 1) // 13
        ctx[7 + i * 3] = r / 12.0
        ctx[8 + i * 3] = 1.0 if sum((1 for x in hole if (x - 1) % 13 == r)) > 1 else 0.0
        ctx[9 + i * 3] = sum((1 for b in board if b and (b - 1) // 13 == s)) / 5.0
    ctx[15] = len(board) / 5.0
    idx = int(np.argmax(DISC.forward(toks[None], ctx[None])[0]))
    return {'type': 'discard', 'card': msg['hole_cards'][idx]}

def safe_action(msg):
    legal = msg['legal_actions']
    if msg.get('to_call', 0) > 0:
        return {'type': 'action', 'action': 'call' if 'call' in legal else 'fold' if 'fold' in legal else legal[0]}
    return {'type': 'action', 'action': 'check' if 'check' in legal else 'fold' if 'fold' in legal else legal[0]}

def main():
    load_models()
    for raw in sys.stdin:
        raw = raw.strip()
        if not raw:
            continue
        msg = json.loads(raw)
        t = msg.get('type')
        try:
            if t == 'new_hand':
                H.hand = msg['hand_id']
                H.seat = _SEATS[msg['seat']]
                H.hole = list(msg['hole_cards'])
                H.opp_disc = None
                H.seq = 0
            elif t == 'discard_result':
                H.hole = list(msg['hole_cards'])
                H.opp_disc = msg['opp_discard']
            elif t == 'action_request':
                sys.stdout.write(json.dumps(handle_action(msg)) + '\n')
                sys.stdout.flush()
            elif t == 'discard_request':
                sys.stdout.write(json.dumps(handle_discard(msg)) + '\n')
                sys.stdout.flush()
            elif t == 'hand_result':
                pass
            elif t == 'match_end':
                break
        except Exception:
            sys.stderr.write(traceback.format_exc() + '\n')
            sys.stderr.flush()
            if t == 'action_request':
                sys.stdout.write(json.dumps(safe_action(msg)) + '\n')
                sys.stdout.flush()
            elif t == 'discard_request':
                hole = msg['hole_cards']
                lowest = min(hole, key=lambda c: CARD_ID[c])
                sys.stdout.write(json.dumps({'type': 'discard', 'card': lowest}) + '\n')
                sys.stdout.flush()
if __name__ == '__main__':
    main()